#include <zephyr/modem/pipe.h>
#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(modem_pipe, CONFIG_MODEM_MODULES_LOG_LEVEL);

#define MODEM_PIPE_OPEN_TIMEOUT K_MSEC(10000)
#define MODEM_PIPE_CLOSE_TIMEOUT K_MSEC(10000)

#define MODEM_PIPE_EVENT_OPEN_BIT	(0)
#define MODEM_PIPE_EVENT_CLOSE_BIT	(1)

#define MODEM_PIPE_STATE_OPEN_BIT		(0)
#define MODEM_PIPE_STATE_RECEIVE_READY_BIT	(1)
#define MODEM_PIPE_STATE_TRANSMIT_IDLE_BIT	(2)

static void modem_pipe_call_callback(struct modem_pipe *pipe, enum modem_pipe_event event)
{
	if (pipe->callback != NULL) {
		pipe->callback(pipe, event, pipe->user_data);
	}
}

void modem_pipe_init(struct modem_pipe *pipe, void *data, const struct modem_pipe_api *api)
{
	__ASSERT_NO_MSG(pipe != NULL);
	__ASSERT_NO_MSG(data != NULL);
	__ASSERT_NO_MSG(api != NULL);

	pipe->data = data;
	pipe->api = api;
	pipe->callback = NULL;
	pipe->user_data = NULL;
	pipe->state = 0;

	atomic_set_bit(&pipe->state, MODEM_PIPE_STATE_TRANSMIT_IDLE_BIT);
	k_mutex_init(&pipe->lock);
	k_condvar_init(&pipe->condvar);
}

int modem_pipe_open(struct modem_pipe *pipe, k_timeout_t timeout)
{
	int ret;

	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		k_mutex_unlock(&pipe->lock);
		return 0;
	}

	ret = pipe->api->open(pipe->data);
	if (ret < 0) {
		k_mutex_unlock(&pipe->lock);
		return ret;
	}

	if (atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		k_mutex_unlock(&pipe->lock);
		return 0;
	}

	ret = k_condvar_wait(&pipe->condvar, &pipe->lock, timeout);
	k_mutex_unlock(&pipe->lock);
	return ret;
}

int modem_pipe_open_async(struct modem_pipe *pipe)
{
	int ret;

	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_OPENED);
		k_mutex_unlock(&pipe->lock);
		return 0;
	}

	ret = pipe->api->open(pipe->data);
	k_mutex_unlock(&pipe->lock);
	return ret;
}

void modem_pipe_attach(struct modem_pipe *pipe, modem_pipe_api_callback callback, void *user_data)
{
	k_mutex_lock(&pipe->lock, K_FOREVER);
	pipe->callback = callback;
	pipe->user_data = user_data;

	if (atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_RECEIVE_READY_BIT)) {
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_RECEIVE_READY);
	}

	if (atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_TRANSMIT_IDLE_BIT)) {
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_TRANSMIT_IDLE);
	}
	k_mutex_unlock(&pipe->lock);
}

int modem_pipe_transmit(struct modem_pipe *pipe, const uint8_t *buf, size_t size)
{
	int ret;

	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (!atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		k_mutex_unlock(&pipe->lock);
		return -EPERM;
	}

	atomic_clear_bit(&pipe->state, MODEM_PIPE_STATE_TRANSMIT_IDLE_BIT);
	ret = pipe->api->transmit(pipe->data, buf, size);
	k_mutex_unlock(&pipe->lock);
	return ret;
}

int modem_pipe_receive(struct modem_pipe *pipe, uint8_t *buf, size_t size)
{
	int ret;

	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (!atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		k_mutex_unlock(&pipe->lock);
		return -EPERM;
	}

	ret = pipe->api->receive(pipe->data, buf, size);
	if (ret <= 0) {
		atomic_clear_bit(&pipe->state, MODEM_PIPE_STATE_RECEIVE_READY_BIT);
	}

	k_mutex_unlock(&pipe->lock);
	return ret;
}

void modem_pipe_release(struct modem_pipe *pipe)
{
	k_mutex_lock(&pipe->lock, K_FOREVER);
	pipe->callback = NULL;
	pipe->user_data = NULL;
	k_mutex_unlock(&pipe->lock);
}

int modem_pipe_close(struct modem_pipe *pipe, k_timeout_t timeout)
{
	int ret;

	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (!atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		k_mutex_unlock(&pipe->lock);
		return 0;
	}

	ret = pipe->api->close(pipe->data);
	if (ret < 0) {
		k_mutex_unlock(&pipe->lock);
		return ret;
	}

	if (!atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		k_mutex_unlock(&pipe->lock);
		return 0;
	}

	ret = k_condvar_wait(&pipe->condvar, &pipe->lock, timeout);
	k_mutex_unlock(&pipe->lock);
	return ret;
}

int modem_pipe_close_async(struct modem_pipe *pipe)
{
	int ret;

	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (!atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_CLOSED);
		k_mutex_unlock(&pipe->lock);
		return 0;
	}

	ret = pipe->api->close(pipe->data);
	k_mutex_unlock(&pipe->lock);
	return ret;
}

void modem_pipe_notify_opened(struct modem_pipe *pipe)
{
	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (!atomic_test_and_set_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_OPENED);
		k_condvar_signal(&pipe->condvar);
	}
	k_mutex_unlock(&pipe->lock);
}

void modem_pipe_notify_closed(struct modem_pipe *pipe)
{
	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (atomic_test_and_clear_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		atomic_clear_bit(&pipe->state, MODEM_PIPE_STATE_RECEIVE_READY_BIT);
		atomic_set_bit(&pipe->state, MODEM_PIPE_STATE_TRANSMIT_IDLE_BIT);
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_CLOSED);
		k_condvar_signal(&pipe->condvar);
	}
	k_mutex_unlock(&pipe->lock);
}

void modem_pipe_notify_receive_ready(struct modem_pipe *pipe)
{
	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		atomic_set_bit(&pipe->state, MODEM_PIPE_STATE_RECEIVE_READY_BIT);
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_RECEIVE_READY);
	}
	k_mutex_unlock(&pipe->lock);
}

void modem_pipe_notify_transmit_idle(struct modem_pipe *pipe)
{
	k_mutex_lock(&pipe->lock, K_FOREVER);
	if (atomic_test_bit(&pipe->state, MODEM_PIPE_STATE_OPEN_BIT)) {
		atomic_set_bit(&pipe->state, MODEM_PIPE_STATE_TRANSMIT_IDLE_BIT);
		modem_pipe_call_callback(pipe, MODEM_PIPE_EVENT_TRANSMIT_IDLE);
	}
	k_mutex_unlock(&pipe->lock);
}

void modem_pipe_userdata_set(struct modem_pipe *pipe, void *user_data)
{
	k_mutex_lock(&pipe->lock, K_FOREVER);
	pipe->user_data = user_data;
	k_mutex_unlock(&pipe->lock);
}

void *modem_pipe_userdata_get(struct modem_pipe *pipe)
{
	void *user_data;

	k_mutex_lock(&pipe->lock, K_FOREVER);
	user_data = pipe->user_data;
	k_mutex_unlock(&pipe->lock);
	return user_data;
}
